A1Bulk.ListOfA1:
{{- $d := .Doc}}
{{- range .Related.a1}}
{{- $tin := digits .nik}}
{{- if eq (len (digits .npwp)) 16}}{{$tin = digits .npwp}}{{else if eq (len (digits .npwp)) 15}}{{$tin = print "0" (digits .npwp)}}{{end}}

			No
			{{dec .month_start 0}}
			{{dec .month_end 0}}
			{{.tax_year}}
			Resident

			{{$tin}}
			{{if eq (slice .ptkp_status 0 1) "t"}}TK/{{slice .ptkp_status 2}}{{else}}K/{{slice .ptkp_status 1}}{{end}}
			{{if eq .withholding_status "full_year"}}FullYear{{else}}PartialYear{{end}}
			{{or .position "Staff"}}
			21-100-01
			0
			{{dec .gross_salary 0}}
			No
			0
			{{dec .other_benefit 0}}
			0
			{{dec .insurance_employer 0}}
			0
			{{dec .bonus_thr 0}}
			{{dec .pension_contribution 0}}
			0

			N/A
			0
			{{$d.seller_nitku}}
			{{isodate $d.withholding_date}}

{{- end}}
